import app from 'flarum/forum/app';
import Page from 'flarum/common/components/Page';
import PageStructure from 'flarum/forum/components/PageStructure';
import IndexSidebar from 'flarum/forum/components/IndexSidebar';
import LinkButton from 'flarum/common/components/LinkButton';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import extractText from 'flarum/common/utils/extractText';
import { t } from '../../common/t';
import { store } from '../../common/api';
import ProductCard from '../components/ProductCard';

/** /store — everything for sale, grouped by what it opens. */
export default class StorePage extends Page {
  products = [];
  meta = {
    owned: [],
    providers: [],
    termsUrl: null
  };
  loading = true;
  oninit(vnode) {
    super.oninit(vnode);
    const title = extractText(t('forum.store.title'));
    app.setTitle(title);
    app.history.push('kiosk.store', title);

    // /store?seller=12: one member's listings.
    const seller = Number(m.route.param('seller')) || 0;
    store(seller ? {
      seller
    } : undefined).then(({
      data,
      meta
    }) => {
      this.products = data;
      this.meta = meta;
      this.loading = false;
      m.redraw();
    }, () => {
      this.loading = false;
      m.redraw();
    });
  }
  onupdate() {
    // /store?product=gold scrolls to that card once it has drawn.
    const slug = m.route.param('product');
    if (slug && !this.scrolled && !this.loading) {
      this.scrolled = true;
      document.getElementById('kiosk-' + slug)?.scrollIntoView({
        block: 'center'
      });
    }
  }
  scrolled = false;
  view() {
    const highlight = m.route.param('product');
    return m(PageStructure, {
      className: "KioskStorePage",
      sidebar: () => m(IndexSidebar, null)
    }, m("div", {
      className: "KioskPageHead"
    }, m("h2", {
      className: "KioskPageHead-title"
    }, this.products[0]?.seller && m.route.param('seller') ? t('forum.store.by_seller', {
      name: this.products[0].seller.displayName
    }) : t('forum.store.title')), m("div", {
      className: "KioskPageHead-actions"
    }, app.forum.attribute('kioskCanSell') ? m(LinkButton, {
      className: "Button",
      icon: "fas fa-cash-register",
      href: app.route('kiosk.selling')
    }, t('forum.selling.title')) : null, app.session.user ? m(LinkButton, {
      className: "Button",
      icon: "fas fa-receipt",
      href: app.route('kiosk.purchases')
    }, t('forum.purchases.title')) : null)), this.loading ? m(LoadingIndicator, {
      display: "block"
    }) : this.products.length ? m("div", {
      className: "KioskGrid"
    }, this.products.map(product => m(ProductCard, {
      product: product,
      meta: this.meta,
      highlight: product.slug === highlight
    }))) : m("p", {
      className: "KioskEmpty"
    }, t('forum.store.empty')));
  }
}
flarum.reg.add('ernestdefoe-kiosk', 'forum/pages/StorePage', StorePage);